head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getOverflowY]<br/>GridView 컴포넌트의 overflowY 속성값을 반환합니다.",
    "validation" : [
        "auto 설정 시, getOverflowY() 가 overflowY 속성값 'auto' 를 반환합니다.",
        "hidden 설정 시, getOverflowY() 가 overflowY 속성값 'hidden' 를 반환합니다.",
        "scroll 설정 시, getOverflowY() 가 overflowY 속성값 'scroll' 를 반환합니다.",
        "미설정 시, getOverflowY() 가 기본값 'auto' 를 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 바인딩 DataList 생성 (25 Row - 세로 스크롤 확보용)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="name1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="name2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="name3" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true">';
    let arrNames = ['김철수', '이영희', '박민준', '최서연', '정도윤', '강하은'];
    let arrDept = ['영업1팀', '영업2팀', '개발팀', '인사팀', '재무팀', '기획팀'];
    for (var i = 0; i < 25; i++) {
        strDlt += '<w2:row>';
        strDlt += '<col1><![CDATA[' + (i + 1) + ']]></col1>';
        strDlt += '<col2><![CDATA[' + arrNames[i % arrNames.length] + ']]></col2>';
        strDlt += '<col3><![CDATA[' + arrDept[i % arrDept.length] + ']]></col3>';
        strDlt += '</w2:row>';
    }
    strDlt += '</w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 조건 설정 - con_overflowY 값 적용 (미설정 시 overflowY 속성 자체를 생략 → 기본값 확인)
    let ovY = con_overflowY.getText();
    let properties = {
        dataList: "data:dlt_bind",
    };
    if (ovY !== '') {
        properties.overflowY = ovY;
    }

    let cList = $c.gcm.createCList(properties);

    // 테스트 참고 라벨 (검증 운영 정보) — grid 생성 전에 먼저 생성
    $c.gcm.createLabel('label="[전제] con_overflowY 로 세로 스크롤 방식(auto/hidden/scroll/미설정) 선택 후 (Target 재생성) 클릭\n[절차] (getOverflowY) 클릭\n[확인] 반환값이 현재 overflowY 속성값(auto/hidden/scroll) 과 일치, 미설정 시 기본값 auto"', '', 'label1');

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" id="" style="width:350px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="사원 목록"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="hcol1" value="사번"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="이름"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol3" value="부서"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col1" displayType="label"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" displayType="label"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" displayType="label"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    // target 생성
    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// getOverflowY : 현재 overflowY 속성값 반환 (메인 검증)
scwin.btn_getOverflowY_onclick = function (e) {
    let rtn = target1.getOverflowY();
    wf_body_bottom.getObj("scwin").setReturnValue("getOverflowY : " + rtn);
};
